class ParallelSlotsAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma_200 = self.SMA(self.spy, 200, Resolution.Daily)
        self.spy_sma_50 = self.SMA(self.spy, 50, Resolution.Daily)
        self.aapl_rsi_14 = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily,
        )

        self.spy_lot = 0
        self.aapl_lot = 0
        self.aapl_red_streak = 0
        self.previous_closes = {}
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None

        # This supplies enough trading bars for the longest indicator and also
        # lets the prior-day values needed by crossover and streak rules form.
        self.SetWarmUp(201, Resolution.Daily)

    def OnData(self, data):
        # The entire system is evaluated only when all five daily bars exist.
        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        closes = {
            ticker: data.Bars[symbol].Close
            for ticker, symbol in self.symbols.items()
        }

        previous_aapl_close = self.previous_closes.get("AAPL")
        if previous_aapl_close is None:
            self.aapl_red_streak = 0
        elif closes["AAPL"] < previous_aapl_close:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0

        indicators_ready = (
            self.spy_sma_200.IsReady
            and self.spy_sma_50.IsReady
            and self.aapl_rsi_14.IsReady
        )
        prior_values_ready = (
            "SPY" in self.previous_closes
            and "AAPL" in self.previous_closes
            and self.previous_spy_sma_200 is not None
            and self.previous_spy_sma_50 is not None
        )

        if not self.IsWarmingUp and indicators_ready and prior_values_ready:
            self._evaluate_spy_slot(closes["SPY"])
            self._evaluate_aapl_slot(closes["AAPL"])

        self.previous_closes = closes
        if self.spy_sma_200.IsReady:
            self.previous_spy_sma_200 = self.spy_sma_200.Current.Value
        if self.spy_sma_50.IsReady:
            self.previous_spy_sma_50 = self.spy_sma_50.Current.Value

    def _evaluate_spy_slot(self, close):
        previous_close = self.previous_closes["SPY"]
        sma_50 = self.spy_sma_50.Current.Value
        sma_200 = self.spy_sma_200.Current.Value

        # Sells are evaluated before buys.  The sell crossover is the close
        # crossing below its 50-day SMA.
        if self.spy_lot > 0:
            crossed_below_50 = (
                previous_close >= self.previous_spy_sma_50
                and close < sma_50
            )
            if crossed_below_50:
                self.MarketOrder(self.spy, -self.spy_lot)
                self.spy_lot = 0
            return

        crossed_above_200 = (
            previous_close <= self.previous_spy_sma_200
            and close > sma_200
        )
        if crossed_above_200:
            quantity = self.CalculateOrderQuantity(self.spy, 0.40)
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.spy_lot = quantity

    def _evaluate_aapl_slot(self, close):
        if self.aapl_lot > 0:
            if self.aapl_rsi_14.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.aapl_lot)
                self.aapl_lot = 0
            return

        cash_amount = 20_000
        if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= cash_amount:
            quantity = int(cash_amount // close)
            if quantity > 0:
                self.MarketOrder(self.aapl, quantity)
                self.aapl_lot = quantity

