class IndependentDailyStrategiesAlgorithm(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy_sma_200 = self.sma(
            self.symbols["SPY"], 200, Resolution.DAILY
        )
        self.spy_sma_50 = self.sma(
            self.symbols["SPY"], 50, Resolution.DAILY
        )
        self.aapl_rsi_14 = self.rsi(
            self.symbols["AAPL"], 14, MovingAverageType.WILDERS,
            Resolution.DAILY
        )

        self.spy_lot = 0
        self.aapl_lot = 0
        self.previous_spy_close = None
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.set_warm_up(200, Resolution.DAILY)

    def on_data(self, data):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        spy_bar = data.bars[spy] if data.bars.contains_key(spy) else None
        aapl_bar = data.bars[aapl] if data.bars.contains_key(aapl) else None

        spy_crossed_above_200 = False
        spy_crossed_below_50 = False
        if spy_bar is not None:
            spy_close = float(spy_bar.close)
            if (
                self.previous_spy_close is not None
                and self.previous_spy_sma_200 is not None
                and self.spy_sma_200.is_ready
            ):
                spy_crossed_above_200 = (
                    self.previous_spy_close <= self.previous_spy_sma_200
                    and spy_close > self.spy_sma_200.current.value
                )
            if (
                self.previous_spy_close is not None
                and self.previous_spy_sma_50 is not None
                and self.spy_sma_50.is_ready
            ):
                spy_crossed_below_50 = (
                    self.previous_spy_close >= self.previous_spy_sma_50
                    and spy_close < self.spy_sma_50.current.value
                )

            self.previous_spy_close = spy_close
            if self.spy_sma_200.is_ready:
                self.previous_spy_sma_200 = self.spy_sma_200.current.value
            if self.spy_sma_50.is_ready:
                self.previous_spy_sma_50 = self.spy_sma_50.current.value

        if aapl_bar is not None:
            aapl_close = float(aapl_bar.close)
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_close

        if any(not data.bars.contains_key(symbol) for symbol in self.symbols.values()):
            return
        if (
            self.is_warming_up
            or not self.spy_sma_200.is_ready
            or not self.spy_sma_50.is_ready
            or not self.aapl_rsi_14.is_ready
        ):
            return

        if self.spy_lot > 0:
            if spy_crossed_below_50:
                self.market_order(spy, -self.spy_lot)
                self.spy_lot = 0
        elif spy_crossed_above_200:
            quantity = floor(
                0.40 * float(self.portfolio.total_portfolio_value)
                / float(data.bars[spy].close)
            )
            if quantity > 0:
                self.market_order(spy, quantity)
                self.spy_lot = quantity

        if self.aapl_lot > 0:
            if self.aapl_rsi_14.current.value > 60:
                self.market_order(aapl, -self.aapl_lot)
                self.aapl_lot = 0
        elif self.aapl_red_streak >= 3 and float(self.portfolio.cash) >= 20_000:
            quantity = floor(20_000 / float(data.bars[aapl].close))
            if quantity > 0:
                self.market_order(aapl, quantity)
                self.aapl_lot = quantity

