class IndependentDailyStrategiesAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=201)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

        # The extra bar supplies yesterday's fully formed 200-day average for
        # the first possible crossover comparison.
        self.SetWarmUp(201, Resolution.Daily)

    def OnData(self, data: Slice):
        bars = {}
        complete_slice = True
        for ticker, symbol in self.symbols.items():
            if not data.Bars.ContainsKey(symbol):
                complete_slice = False
            else:
                bars[ticker] = data.Bars[symbol]

        spy_crossed_above_200 = False
        spy_crossed_50 = False

        if "SPY" in bars:
            close = float(bars["SPY"].Close)
            if len(self.spy_closes) >= 200:
                today_sma_200 = (sum(list(self.spy_closes)[-199:]) + close) / 200.0
                yesterday_sma_200 = sum(list(self.spy_closes)[-200:]) / 200.0
                yesterday_close = self.spy_closes[-1]
                spy_crossed_above_200 = (
                    yesterday_close <= yesterday_sma_200
                    and close > today_sma_200
                )

            if len(self.spy_closes) >= 50:
                today_sma_50 = (sum(list(self.spy_closes)[-49:]) + close) / 50.0
                yesterday_sma_50 = sum(list(self.spy_closes)[-50:]) / 50.0
                yesterday_close = self.spy_closes[-1]
                spy_crossed_50 = (
                    (yesterday_close <= yesterday_sma_50 and close > today_sma_50)
                    or (yesterday_close >= yesterday_sma_50 and close < today_sma_50)
                )

            self.spy_closes.append(close)

        if "AAPL" in bars:
            close = float(bars["AAPL"].Close)
            if self.aapl_previous_close is not None:
                if close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = close
            self.aapl_rsi.Update(IndicatorDataPoint(bars["AAPL"].EndTime, close))

        if self.IsWarmingUp or not complete_slice:
            return

        # Sells are evaluated before buys.
        if self.strategy_a_shares > 0 and spy_crossed_50:
            self.MarketOrder(self.symbols["SPY"], -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if (
            self.strategy_b_shares > 0
            and self.aapl_rsi.IsReady
            and self.aapl_rsi.Current.Value > 60
        ):
            self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and len(self.spy_closes) >= 201 and spy_crossed_above_200:
            close = float(bars["SPY"].Close)
            shares = floor((0.40 * float(self.Portfolio.TotalPortfolioValue)) / close)
            if shares > 0:
                self.MarketOrder(self.symbols["SPY"], shares)
                self.strategy_a_shares = shares

        if self.strategy_b_shares == 0 and self.aapl_rsi.IsReady and self.aapl_red_streak >= 3:
            if float(self.Portfolio.Cash) >= 20_000:
                close = float(bars["AAPL"].Close)
                shares = floor(20_000 / close)
                if shares > 0:
                    self.MarketOrder(self.symbols["AAPL"], shares)
                    self.strategy_b_shares = shares

