class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma_200 = SimpleMovingAverage(200)
        self.spy_sma_50 = SimpleMovingAverage(50)
        self.aapl_rsi_14 = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_spy_close = None
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_order_pending = False
        self.aapl_order_pending = False

    def OnData(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if data.Bars.ContainsKey(spy):
            spy_bar = data.Bars[spy]
            self.spy_sma_200.Update(spy_bar.EndTime, spy_bar.Close)
            self.spy_sma_50.Update(spy_bar.EndTime, spy_bar.Close)
        else:
            spy_bar = None

        if data.Bars.ContainsKey(aapl):
            aapl_bar = data.Bars[aapl]
            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi_14.Update(aapl_bar.EndTime, aapl_bar.Close)
        else:
            aapl_bar = None

        complete_day = all(data.Bars.ContainsKey(symbol) for symbol in self.symbols.values())

        if complete_day and self._all_state_is_ready():
            self._evaluate_spy(spy_bar)
            self._evaluate_aapl(aapl_bar)

        if spy_bar is not None:
            self.previous_spy_close = spy_bar.Close
            if self.spy_sma_200.IsReady:
                self.previous_spy_sma_200 = self.spy_sma_200.Current.Value
            if self.spy_sma_50.IsReady:
                self.previous_spy_sma_50 = self.spy_sma_50.Current.Value

        if aapl_bar is not None:
            self.previous_aapl_close = aapl_bar.Close

    def _all_state_is_ready(self):
        return (
            self.spy_sma_200.IsReady
            and self.spy_sma_50.IsReady
            and self.aapl_rsi_14.IsReady
            and self.previous_spy_close is not None
            and self.previous_spy_sma_200 is not None
            and self.previous_spy_sma_50 is not None
            and self.previous_aapl_close is not None
        )

    def _evaluate_spy(self, bar):
        if self.spy_order_pending:
            return

        close = bar.Close
        if self.spy_lot > 0:
            crossed_below_sma_50 = (
                self.previous_spy_close >= self.previous_spy_sma_50
                and close < self.spy_sma_50.Current.Value
            )
            if crossed_below_sma_50:
                self.spy_order_pending = True
                self.MarketOrder(self.symbols["SPY"], -self.spy_lot, tag="Strategy A sell")
            return

        crossed_above_sma_200 = (
            self.previous_spy_close <= self.previous_spy_sma_200
            and close > self.spy_sma_200.Current.Value
        )
        if crossed_above_sma_200:
            quantity = self.CalculateOrderQuantity(self.symbols["SPY"], 0.40)
            if quantity > 0:
                self.spy_order_pending = True
                self.MarketOrder(self.symbols["SPY"], quantity, tag="Strategy A buy")

    def _evaluate_aapl(self, bar):
        if self.aapl_order_pending:
            return

        if self.aapl_lot > 0:
            if self.aapl_rsi_14.Current.Value > 60:
                self.aapl_order_pending = True
                self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot, tag="Strategy B sell")
            return

        if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
            quantity = int(20_000 // bar.Close)
            if quantity > 0:
                self.aapl_order_pending = True
                self.MarketOrder(self.symbols["AAPL"], quantity, tag="Strategy B buy")

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status not in (OrderStatus.Filled, OrderStatus.PartiallyFilled):
            if order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                if order_event.Symbol == self.symbols["SPY"]:
                    self.spy_order_pending = False
                elif order_event.Symbol == self.symbols["AAPL"]:
                    self.aapl_order_pending = False
            return

        if order_event.Symbol == self.symbols["SPY"]:
            self.spy_lot += order_event.FillQuantity
            if order_event.Status == OrderStatus.Filled:
                self.spy_order_pending = False
        elif order_event.Symbol == self.symbols["AAPL"]:
            self.aapl_lot += order_event.FillQuantity
            if order_event.Status == OrderStatus.Filled:
                self.aapl_order_pending = False

