class IndependentDailyStrategiesAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in self.tickers
        }

        self.spy_sma_200 = SimpleMovingAverage(200)
        self.spy_sma_50 = SimpleMovingAverage(50)
        self.aapl_rsi_14 = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_closes = {}
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None
        self.aapl_red_streak = 0

        self.lots = {"A": 0, "B": 0}
        self.pending_buys = {"A": False, "B": False}
        self.pending_sells = {"A": False, "B": False}

        self.SetWarmUp(201, Resolution.Daily)

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        spy_bar = bars.get("SPY")
        if spy_bar is not None:
            old_sma_200 = (
                self.spy_sma_200.Current.Value if self.spy_sma_200.IsReady else None
            )
            old_sma_50 = (
                self.spy_sma_50.Current.Value if self.spy_sma_50.IsReady else None
            )
            self.spy_sma_200.Update(spy_bar.EndTime, spy_bar.Close)
            self.spy_sma_50.Update(spy_bar.EndTime, spy_bar.Close)
            self.previous_spy_sma_200 = old_sma_200
            self.previous_spy_sma_50 = old_sma_50

        aapl_bar = bars.get("AAPL")
        if aapl_bar is not None:
            previous_aapl_close = self.previous_closes.get("AAPL")
            if previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_bar.Close < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_rsi_14.Update(aapl_bar.EndTime, aapl_bar.Close)

        prior_spy_close = self.previous_closes.get("SPY")
        for ticker, bar in bars.items():
            self.previous_closes[ticker] = bar.Close

        if self.IsWarmingUp or len(bars) != len(self.tickers):
            return

        all_indicators_ready = (
            self.spy_sma_200.IsReady
            and self.spy_sma_50.IsReady
            and self.aapl_rsi_14.IsReady
            and prior_spy_close is not None
            and self.previous_spy_sma_200 is not None
            and self.previous_spy_sma_50 is not None
        )
        if not all_indicators_ready:
            return

        # Sells are evaluated before buys.
        if self.lots["A"] > 0 and not self.pending_sells["A"]:
            crossed_below_sma_50 = (
                prior_spy_close >= self.previous_spy_sma_50
                and spy_bar.Close < self.spy_sma_50.Current.Value
            )
            if crossed_below_sma_50:
                self.pending_sells["A"] = True
                self.MarketOrder(self.symbols["SPY"], -self.lots["A"], tag="A:sell")

        if self.lots["B"] > 0 and not self.pending_sells["B"]:
            if self.aapl_rsi_14.Current.Value > 60:
                self.pending_sells["B"] = True
                self.MarketOrder(self.symbols["AAPL"], -self.lots["B"], tag="B:sell")

        if (
            self.lots["A"] == 0
            and not self.pending_buys["A"]
            and not self.pending_sells["A"]
        ):
            crossed_above_sma_200 = (
                prior_spy_close <= self.previous_spy_sma_200
                and spy_bar.Close > self.spy_sma_200.Current.Value
            )
            if crossed_above_sma_200:
                quantity = self.CalculateOrderQuantity(self.symbols["SPY"], 0.40)
                if quantity > 0:
                    self.pending_buys["A"] = True
                    self.MarketOrder(self.symbols["SPY"], quantity, tag="A:buy")

        if (
            self.lots["B"] == 0
            and not self.pending_buys["B"]
            and not self.pending_sells["B"]
            and self.aapl_red_streak >= 3
            and self.Portfolio.Cash >= 20_000
        ):
            quantity = int(20_000 // aapl_bar.Close)
            if quantity > 0:
                self.pending_buys["B"] = True
                self.MarketOrder(self.symbols["AAPL"], quantity, tag="B:buy")

    def OnOrderEvent(self, order_event: OrderEvent):
        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None or not order.Tag or ":" not in order.Tag:
            return

        strategy, action = order.Tag.split(":", 1)
        if strategy not in self.lots:
            return

        if order_event.Status == OrderStatus.Filled:
            if action == "buy":
                self.lots[strategy] += order_event.FillQuantity
                self.pending_buys[strategy] = False
            elif action == "sell":
                self.lots[strategy] += order_event.FillQuantity
                if self.lots[strategy] <= 0:
                    self.lots[strategy] = 0
                self.pending_sells[strategy] = False
        elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
            if action == "buy":
                self.pending_buys[strategy] = False
            elif action == "sell":
                self.pending_sells[strategy] = False

