class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma_200 = self.SMA(self.spy, 200, Resolution.Daily)
        self.spy_sma_50 = self.SMA(self.spy, 50, Resolution.Daily)
        self.aapl_rsi_14 = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.spy_lot = 0
        self.aapl_lot = 0
        self.previous_spy_close = None
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

    def OnData(self, data: Slice):
        spy_bar = data.Bars[self.spy] if data.Bars.ContainsKey(self.spy) else None
        aapl_bar = data.Bars[self.aapl] if data.Bars.ContainsKey(self.aapl) else None

        # Corporate actions can change the number of shares in an existing lot.
        if self.spy_lot != 0 and self.Portfolio[self.spy].Quantity != 0:
            self.spy_lot = int(self.Portfolio[self.spy].Quantity)
        if self.aapl_lot != 0 and self.Portfolio[self.aapl].Quantity != 0:
            self.aapl_lot = int(self.Portfolio[self.aapl].Quantity)

        if aapl_bar is not None:
            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_bar.Close

        all_bars_present = all(data.Bars.ContainsKey(symbol) for symbol in self.symbols)
        indicators_ready = (
            self.spy_sma_200.IsReady
            and self.spy_sma_50.IsReady
            and self.aapl_rsi_14.IsReady
        )

        if all_bars_present and indicators_ready:
            # Sells are evaluated before buys.
            if self.spy_lot != 0 and self._spy_sma_50_crossed(spy_bar.Close):
                self.MarketOrder(self.spy, -self.spy_lot)
                self.spy_lot = 0

            if self.aapl_lot != 0 and self.aapl_rsi_14.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.aapl_lot)
                self.aapl_lot = 0

            if self.spy_lot == 0 and self._spy_crossed_above_sma_200(spy_bar.Close):
                quantity = self.CalculateOrderQuantity(self.spy, 0.40)
                if quantity > 0:
                    self.MarketOrder(self.spy, quantity)
                    self.spy_lot = quantity

            if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
                allocation = 20_000
                if self.Portfolio.Cash >= allocation:
                    quantity = int(allocation // aapl_bar.Close)
                    if quantity > 0:
                        self.MarketOrder(self.aapl, quantity)
                        self.aapl_lot = quantity

        if spy_bar is not None:
            self.previous_spy_close = spy_bar.Close
            if self.spy_sma_200.IsReady:
                self.previous_spy_sma_200 = self.spy_sma_200.Current.Value
            if self.spy_sma_50.IsReady:
                self.previous_spy_sma_50 = self.spy_sma_50.Current.Value

    def _spy_crossed_above_sma_200(self, close):
        return (
            self.previous_spy_close is not None
            and self.previous_spy_sma_200 is not None
            and self.previous_spy_close <= self.previous_spy_sma_200
            and close > self.spy_sma_200.Current.Value
        )

    def _spy_sma_50_crossed(self, close):
        if self.previous_spy_close is None or self.previous_spy_sma_50 is None:
            return False
        crossed_above = (
            self.previous_spy_close <= self.previous_spy_sma_50
            and close > self.spy_sma_50.Current.Value
        )
        crossed_below = (
            self.previous_spy_close >= self.previous_spy_sma_50
            and close < self.spy_sma_50.Current.Value
        )
        return crossed_above or crossed_below

