class IndependentDailyStrategiesAlgorithm(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(ticker, Resolution.DAILY).symbol

        self.spy_sma_200 = SimpleMovingAverage(200)
        self.spy_sma_50 = SimpleMovingAverage(50)
        self.aapl_rsi_14 = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.previous_spy_close = None
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        bars = {}
        all_bars_present = True
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]
            else:
                all_bars_present = False

        spy_bar = bars.get("SPY")
        aapl_bar = bars.get("AAPL")

        if spy_bar is not None:
            self.spy_sma_200.update(spy_bar.end_time, spy_bar.close)
            self.spy_sma_50.update(spy_bar.end_time, spy_bar.close)

        if aapl_bar is not None:
            if self.previous_aapl_close is not None:
                if aapl_bar.close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi_14.update(aapl_bar.end_time, aapl_bar.close)

        if all_bars_present:
            self._evaluate_strategy_a(spy_bar)
            self._evaluate_strategy_b(aapl_bar)

        if spy_bar is not None:
            self.previous_spy_close = spy_bar.close
            if self.spy_sma_200.is_ready:
                self.previous_spy_sma_200 = self.spy_sma_200.current.value
            if self.spy_sma_50.is_ready:
                self.previous_spy_sma_50 = self.spy_sma_50.current.value

        if aapl_bar is not None:
            self.previous_aapl_close = aapl_bar.close

    def _evaluate_strategy_a(self, bar):
        indicators_ready = self.spy_sma_200.is_ready and self.spy_sma_50.is_ready
        previous_values_ready = (
            self.previous_spy_close is not None
            and self.previous_spy_sma_200 is not None
            and self.previous_spy_sma_50 is not None
        )
        if not indicators_ready or not previous_values_ready:
            return

        close = bar.close
        if self.strategy_a_shares > 0:
            crossed_below_sma_50 = (
                self.previous_spy_close >= self.previous_spy_sma_50
                and close < self.spy_sma_50.current.value
            )
            if crossed_below_sma_50:
                self.market_order(self.symbols["SPY"], -self.strategy_a_shares)
                self.strategy_a_shares = 0
            return

        crossed_above_sma_200 = (
            self.previous_spy_close <= self.previous_spy_sma_200
            and close > self.spy_sma_200.current.value
        )
        if crossed_above_sma_200:
            shares = floor(float(self.portfolio.total_portfolio_value * Decimal("0.40") / close))
            if shares > 0:
                self.market_order(self.symbols["SPY"], shares)
                self.strategy_a_shares = shares

    def _evaluate_strategy_b(self, bar):
        if not self.aapl_rsi_14.is_ready or self.previous_aapl_close is None:
            return

        if self.strategy_b_shares > 0:
            if self.aapl_rsi_14.current.value > 60:
                self.market_order(self.symbols["AAPL"], -self.strategy_b_shares)
                self.strategy_b_shares = 0
            return

        cash_to_invest = Decimal("20000")
        if self.aapl_red_streak >= 3 and self.portfolio.cash >= cash_to_invest:
            shares = floor(float(cash_to_invest / bar.close))
            if shares > 0:
                self.market_order(self.symbols["AAPL"], shares)
                self.strategy_b_shares = shares

