                ticker, Resolution.DAILY
            ).symbol

        self.spy_sma_200 = SimpleMovingAverage(200)
        self.spy_sma_50 = SimpleMovingAverage(50)
        self.aapl_rsi_14 = RelativeStrengthIndex(
            14, MovingAverageType.WILDERS
        )

        self.previous_closes = {}
        self.previous_spy_200_difference = None
        self.previous_spy_50_difference = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]

        self._update_market_state(bars)

        if len(bars) != len(self.symbols):
            if "SPY" in bars and self.spy_sma_200.is_ready:
                spy_close = bars["SPY"].close
                self.previous_spy_200_difference = (
                    spy_close - self.spy_sma_200.current.value
                )
                self.previous_spy_50_difference = (
                    spy_close - self.spy_sma_50.current.value
                )
            return

        spy = bars["SPY"]
        aapl = bars["AAPL"]

        spy_indicators_ready = self.spy_sma_200.is_ready and self.spy_sma_50.is_ready
        current_spy_200_difference = None
        current_spy_50_difference = None
        if spy_indicators_ready:
            current_spy_200_difference = spy.close - self.spy_sma_200.current.value
            current_spy_50_difference = spy.close - self.spy_sma_50.current.value

        if self.strategy_a_shares > 0:
            crosses_below_sma_50 = (
                self.previous_spy_50_difference is not None
                and self.previous_spy_50_difference >= 0
                and current_spy_50_difference < 0
            )
            if crosses_below_sma_50:
                self.market_order(self.symbols["SPY"], -self.strategy_a_shares)
                self.strategy_a_shares = 0
        elif spy_indicators_ready:
            crosses_above_sma_200 = (
                self.previous_spy_200_difference is not None
                and self.previous_spy_200_difference <= 0
                and current_spy_200_difference > 0
            )
            if crosses_above_sma_200:
                shares = int((self.portfolio.total_portfolio_value * 0.40) // spy.close)
                if shares > 0:
                    self.market_order(self.symbols["SPY"], shares)
                    self.strategy_a_shares = shares

        if self.strategy_b_shares > 0:
            if self.aapl_rsi_14.is_ready and self.aapl_rsi_14.current.value > 60:
                self.market_order(self.symbols["AAPL"], -self.strategy_b_shares)
                self.strategy_b_shares = 0
        elif self.aapl_red_streak >= 3 and self.portfolio.cash >= 20_000:
            shares = int(20_000 // aapl.close)
            if shares > 0:
                self.market_order(self.symbols["AAPL"], shares)
                self.strategy_b_shares = shares

        if spy_indicators_ready:
            self.previous_spy_200_difference = current_spy_200_difference
            self.previous_spy_50_difference = current_spy_50_difference

    def _update_market_state(self, bars):
        for ticker, bar in bars.items():
            previous_close = self.previous_closes.get(ticker)

            if ticker == "SPY":
                self.spy_sma_200.update(bar.end_time, bar.close)
                self.spy_sma_50.update(bar.end_time, bar.close)
            elif ticker == "AAPL":
                self.aapl_rsi_14.update(bar.end_time, bar.close)
                if previous_close is None or bar.close >= previous_close:
                    self.aapl_red_streak = 0
                else:
                    self.aapl_red_streak += 1

            self.previous_closes[ticker] = bar.close

