class ParallelDailyStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=200)
        self.previous_spy_close = None
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        previous_spy_close = self.previous_spy_close
        previous_spy_sma_200 = self.previous_spy_sma_200
        previous_spy_sma_50 = self.previous_spy_sma_50

        if "SPY" in bars:
            spy_close = float(bars["SPY"].Close)
            self.spy_closes.append(spy_close)
            self.previous_spy_close = spy_close
        else:
            spy_close = None

        if len(self.spy_closes) == 200:
            spy_sma_200 = sum(self.spy_closes) / 200.0
            spy_sma_50 = sum(list(self.spy_closes)[-50:]) / 50.0
            self.previous_spy_sma_200 = spy_sma_200
            self.previous_spy_sma_50 = spy_sma_50
        else:
            spy_sma_200 = None
            spy_sma_50 = None

        previous_aapl_close = self.previous_aapl_close
        if "AAPL" in bars:
            aapl_bar = bars["AAPL"]
            aapl_close = float(aapl_bar.Close)
            if previous_aapl_close is not None and aapl_close < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)
        else:
            aapl_close = None

        if len(bars) != len(self.symbols):
            return

        spy_history_ready = (
            spy_sma_200 is not None
            and previous_spy_close is not None
            and previous_spy_sma_200 is not None
            and previous_spy_sma_50 is not None
        )

        # Evaluate every sell before either strategy's buy.
        if self.spy_lot > 0 and spy_history_ready:
            crossed_sma_50 = (
                previous_spy_close <= previous_spy_sma_50
                and spy_close > spy_sma_50
            ) or (
                previous_spy_close >= previous_spy_sma_50
                and spy_close < spy_sma_50
            )
            if crossed_sma_50:
                self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0

        if self.aapl_lot > 0 and self.aapl_rsi.IsReady:
            if float(self.aapl_rsi.Current.Value) > 60.0:
                self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0

        if self.spy_lot == 0 and spy_history_ready:
            crossed_above_sma_200 = (
                previous_spy_close <= previous_spy_sma_200
                and spy_close > spy_sma_200
            )
            if crossed_above_sma_200:
                quantity = floor((0.40 * float(self.Portfolio.TotalPortfolioValue)) / spy_close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["SPY"], quantity)
