        # Market-state values continue to advance for every ticker whose bar is
        # present, even when another ticker is missing from the slice.
        if bars.ContainsKey(self.symbols["SPY"]):
            self.spy_closes.append(float(bars[self.symbols["SPY"]].Close))

        if bars.ContainsKey(self.symbols["AAPL"]):
            aapl_bar = bars[self.symbols["AAPL"]]
            aapl_close = float(aapl_bar.Close)
            if self.aapl_previous_close is None:
