        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if data.bars.contains_key(spy):
            spy_bar = data.bars[spy]
            self.spy_sma_200.update(self.time, spy_bar.close)
            self.spy_sma_50.update(self.time, spy_bar.close)

        if data.bars.contains_key(aapl):
            aapl_bar = data.bars[aapl]
            self.aapl_rsi_14.update(self.time, aapl_bar.close)
            if self.previous_aapl_close is not None:
                if aapl_bar.close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_bar.close

        all_bars_present = all(
            data.bars.contains_key(symbol) for symbol in self.symbols.values()
        )
        if not all_bars_present:
            self._remember_spy_values(data)
            return

        if not (
            self.spy_sma_200.is_ready
            and self.spy_sma_50.is_ready
            and self.aapl_rsi_14.is_ready
        ):
            self._remember_spy_values(data)
            return

        spy_bar = data.bars[spy]
        aapl_bar = data.bars[aapl]

        # Sells are evaluated before buys.
        if self.strategy_a_shares > 0 and self._spy_crossed_below_sma_50(
            spy_bar.close
        ):
            self.market_order(spy, -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if (
            self.strategy_b_shares > 0
            and self.aapl_rsi_14.current.value > 60
        ):
            self.market_order(aapl, -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and self._spy_crossed_above_sma_200(
            spy_bar.close
        ):
            quantity = self.calculate_order_quantity(spy, 0.40)
            if quantity > 0:
                self.market_order(spy, quantity)
                self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            cash_to_invest = 20_000
            if self.portfolio.cash >= cash_to_invest:
                quantity = floor(cash_to_invest / aapl_bar.close)
                if quantity > 0:
                    self.market_order(aapl, quantity)
                    self.strategy_b_shares = quantity

        self._remember_spy_values(data)

    def _spy_crossed_above_sma_200(self, close):
        return (
            self.previous_spy_close is not None
            and self.previous_spy_sma_200 is not None
            and self.previous_spy_close <= self.previous_spy_sma_200
            and close > self.spy_sma_200.current.value
        )

    def _spy_crossed_below_sma_50(self, close):
        return (
            self.previous_spy_close is not None
            and self.previous_spy_sma_50 is not None
            and self.previous_spy_close >= self.previous_spy_sma_50
            and close < self.spy_sma_50.current.value
        )

    def _remember_spy_values(self, data):
        spy = self.symbols["SPY"]
        if not data.bars.contains_key(spy):
            return

        self.previous_spy_close = data.bars[spy].close
        if self.spy_sma_200.is_ready:
            self.previous_spy_sma_200 = self.spy_sma_200.current.value
        if self.spy_sma_50.is_ready:
            self.previous_spy_sma_50 = self.spy_sma_50.current.value

